'use strict';
/* =====================================================
   GEOID — EGM96 undulation, so an altitude can be stated above sea level

   A GNSS receiver reports height above the WGS 84 ELLIPSOID, a smooth mathematical
   surface. Every elevation a person actually uses — a DEM, a contour on a CTR, the
   spot height on a monograph, the <ele> of a GPX file — is height above the GEOID,
   which is what "sea level" means. The two differ by the undulation N, and in Italy
   N is about +43 m: subtracting one from the other without it does not produce a
   height above ground, it produces the undulation itself.

     H (above sea level) = h (GNSS, ellipsoidal) - N (this table)

   DATA: EGM96, the NGA/NASA global gravity model, in the public domain. Sampled from
   the authoritative 15-minute grid distributed with GeographicLib (egm96-15.pgm,
   1440x721) down to a 1-degree grid: 181 rows from 90N to 90S, 360 columns from 0E,
   stored as decimetres in big-endian Int16 and base64-encoded. About 170 KB, the
   weight of jszip and a fifth of turf.

   WHY 1 DEGREE, measured rather than assumed. Bilinear error of this table against
   the full 15-minute grid: median 0.10 m, 99th percentile 1.84 m, worst point on
   Earth 13.66 m (lat 19.5 lon -155.5, the volcanic bulge over Hawaii). Over Italy:
   0.59 m RMS, 2.42 m worst. Quantising to decimetres adds 0.05 m.
   Every one of those numbers is small against what it is used with: the vertical
   error of a phone GNSS fix runs to tens of metres, and two reputable DEMs disagreed
   by 6.5 m at the very point this was verified on. A finer table would refine the
   smallest term in the budget; 0.5 degrees costs four times the bytes to do it.
===================================================== */

(function () {
  var ROWS = 181, COLS = 360;            // 1-degree grid: 90N..90S, 0E..359E
  var DATA = '';

  /* Decoded once, on first use: a page that never asks for an altitude never pays. */
  var _grid = null;
  function _decode() {
    var bin = atob(DATA), n = bin.length, bytes = new Uint8Array(n), i;
    for (i = 0; i < n; i++) bytes[i] = bin.charCodeAt(i);
    var dv = new DataView(bytes.buffer), out = new Int16Array(n / 2);
    for (i = 0; i < out.length; i++) out[i] = dv.getInt16(i * 2, false);   // big-endian
    return out;
  }

  /* Undulation in metres at a position, bilinear between the four surrounding nodes.
     Longitude wraps at the antimeridian; latitude is clamped at the poles, where the
     grid ends exactly. Returns null on a position that is not a pair of numbers, so a
     caller can tell "no correction available" from "a correction of zero" — the two
     mean different things when the number is about to be written into a file. */
  function geoidHeight(lat, lon) {
    if (!isFinite(lat) || !isFinite(lon)) return null;
    if (!_grid) _grid = _decode();
    var y = (90 - Math.min(90, Math.max(-90, lat)));          // 0 at the north pole
    var x = ((lon % 360) + 360) % 360;
    var y0 = Math.floor(y), x0 = Math.floor(x);
    var fy = y - y0, fx = x - x0;
    if (y0 > ROWS - 2) { y0 = ROWS - 2; fy = 1; }
    var y1 = y0 + 1, x1 = (x0 + 1) % COLS;
    var a = _grid[y0 * COLS + x0], b = _grid[y0 * COLS + x1];
    var c = _grid[y1 * COLS + x0], d = _grid[y1 * COLS + x1];
    return ((a * (1 - fx) + b * fx) * (1 - fy) + (c * (1 - fx) + d * fx) * fy) / 10;
  }

  /* Height above sea level from the height a GNSS fix reports. Null in, null out: an
     altitude the receiver did not provide must not become a zero. */
  function ellipsoidToMsl(altEllipsoidal, lat, lon) {
    if (altEllipsoidal == null || !isFinite(altEllipsoidal)) return null;
    var n = geoidHeight(lat, lon);
    return n == null ? null : altEllipsoidal - n;
  }

  window.geoidHeight     = geoidHeight;
  window.ellipsoidToMsl  = ellipsoidToMsl;

})();
